import re

from moler.cmd.commandtextualgeneric import CommandTextualGeneric
from moler.exceptions import ParsingDone


class SyncappmmiStatus(CommandTextualGeneric):
    """Command syncappmmi status."""

    def __init__(self, connection, prompt=None, newline_chars=None, runner=None):
        """
        Command syncappmmi status.

        :param connection: moler connection to device, terminal when command is executed
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(SyncappmmiStatus, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.title = None
        self.source = ""

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "syncappmmi status"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_syncappmmi_status_version(line)
                self._parse_syncappmmi_status_source(line)
                self._parse_syncappmmi_status_tab(line)
                self._parse_syncappmmi_status(line)
                self._parse_syncappmmi_status_title(line)
            except ParsingDone:
                pass
        return super(SyncappmmiStatus, self).on_new_line(line, is_full_line)

    # Sync status: ok                               Duration synced: 01:19:59
    _re_syncappmmi_status = re.compile(r"(?P<NAME>[^:]*):\s{0,3}(?P<VALUE>.*?(?=(\s\s\s|$)))\s*(?P<NAME2>[^:]*)?:?\s?(?P<VALUE2>.*)?")

    def _parse_syncappmmi_status(self, line):
        if self._regex_helper.search_compiled(SyncappmmiStatus._re_syncappmmi_status, line):
            self.current_ret[self.title][self._regex_helper.group("NAME")] = self._regex_helper.group("VALUE")
            if self._regex_helper.group("NAME2"):
                self.current_ret[self.title][self._regex_helper.group("NAME2")] = self._regex_helper.group("VALUE2")
            raise ParsingDone

    #   Status: ok                                  Priority: 0
    _re_syncappmmi_status_tab = re.compile(r"^\s+(?P<NAME>[^:]*):\s{1,3}(?P<VALUE>.*?(?=(\s\s\s|$)))\s*(?P<NAME2>[^:]*)?:?\s?(?P<VALUE2>.*)?")

    def _parse_syncappmmi_status_tab(self, line):
        if self._regex_helper.search_compiled(SyncappmmiStatus._re_syncappmmi_status_tab, line):
            self.current_ret[self.title][self.source][self._regex_helper.group("NAME")] = self._regex_helper.group("VALUE")
            if self._regex_helper.group("NAME2"):
                self.current_ret[self.title][self.source][self._regex_helper.group("NAME2")] = self._regex_helper.group("VALUE2")
            raise ParsingDone

    # -------------------------------- Sync status ---------------------------------
    _re_syncappmmi_status_title = re.compile(r"-+\s(?P<TITLE>.+)\s-+")

    def _parse_syncappmmi_status_title(self, line):
        if self._regex_helper.search_compiled(SyncappmmiStatus._re_syncappmmi_status_title, line):
            self.current_ret[self._regex_helper.group("TITLE")] = {}
            self.title = self._regex_helper.group("TITLE")
            raise ParsingDone

    # Source*: GPS
    _re_syncappmmi_status_source = re.compile(r"Source\*?:\s(?P<SOURCE>\S+)")

    def _parse_syncappmmi_status_source(self, line):
        if self._regex_helper.search_compiled(SyncappmmiStatus._re_syncappmmi_status_source, line):
            self.current_ret[self.title][self._regex_helper.group("SOURCE")] = {}
            self.source = self._regex_helper.group("SOURCE")
            raise ParsingDone

    # bm20131206_11:35-fzmscm-/var/fpwork/fzmscm/production/LNF5.0_ENB_1304_047_00/lteDo/SC_BM-34903
    _re_syncappmmi_status_version = re.compile(r"(?P<VERSION>\w[\w_\-\/:\.]+)")

    def _parse_syncappmmi_status_version(self, line):
        if self._regex_helper.search_compiled(SyncappmmiStatus._re_syncappmmi_status_version, line):
            if self.title == "Version":
                self.current_ret[self.title] = self._regex_helper.group("VERSION")
                raise ParsingDone


